from stance_select_test import PLAN4  # noqa: E402

H = {"arm": None, "S": None}
SIDE = TASK_CFG["arm"]


def descendants(model, root):
    ids = {model.body(root).id}
    for b in range(model.nbody):
        p = b
        while p:
            if p in ids:
                ids.add(b)
                break
            p = int(model.body_parentid[p])
    return ids


def make_hook():
    def hook(modules, model, data):
        m = modules["manipulation"]
        H["arm"], H["S"] = m["arm"], m["state"]
        return modules
    return hook


def pad_frames(model, data):
    """Per finger: the pad patch (vertices within 1 mm of the inner face) with its centre, the axes and the extents. Axes in the world: a = approach (palm to tip), c = closing, w = across."""
    gf = gripper_frame(model, SIDE)
    tcp = model.body(f"openarm_{SIDE}_hand_tcp").id
    Rt = data.xmat[tcp].reshape(3, 3)
    a, c = Rt @ gf["approach_axis"], Rt @ gf["closing_axis"]
    a = a / np.linalg.norm(a)
    c = c / np.linalg.norm(c)
    w = np.cross(c, a)
    out = {"a": a, "c": c, "w": w, "pad_center_world": data.xpos[tcp] + Rt @ gf["pad_center_in_tcp"], "fingers": {}}
    cent = {}
    verts = {}
    for name in ("left_finger", "right_finger"):
        b = model.body(f"openarm_{SIDE}_{name}").id
        gs = [g for g in range(model.ngeom) if int(model.geom_bodyid[g]) == b and (model.geom_contype[g] or model.geom_conaffinity[g])]
        V = np.vstack([_geom_vertices_world(model, data, g) for g in gs])
        verts[name], cent[name] = V, float((V @ c).mean())
    for name, V in verts.items():
        other = [k for k in verts if k != name][0]
        inner = V @ c
        face = inner.max() if cent[name] < cent[other] else inner.min()
        patch = V[np.abs(inner - face) <= 0.001]
        pa, pw = patch @ a, patch @ w
        out["fingers"][name] = {"face_c": float(face), "tip_a": float(pa.max()), "root_a": float(pa.min()), "length_mm": 1000 * float(pa.max() - pa.min()), "width_mm": 1000 * float(pw.max() - pw.min()),
                                "center_a": float(pa.mean()), "center_w": float(pw.mean()), "n_vertices": int(len(patch)), "geoms": [model.geom(g).name for g in gs]}
    return out


def contacts_on_pads(model, data, bg, fgs, pf):
    """Contact points of the beaker on each finger in the pad's coordinates (mm): from the tip and from the patch centre along the approach axis, across the width, and the normal force."""
    f6 = np.zeros(6)
    res = {k: [] for k in fgs}
    a, w = pf["a"], pf["w"]
    for i in range(data.ncon):
        cn = data.contact[i]
        g1, g2 = int(cn.geom1), int(cn.geom2)
        if (g1 in bg) == (g2 in bg):
            continue
        other = g2 if g1 in bg else g1
        for k, gs in fgs.items():
            if other in gs:
                mujoco.mj_contactForce(model, data, i, f6)
                p = np.array(cn.pos)
                f = pf["fingers"][k]
                res[k].append({"from_tip_mm": 1000 * float(f["tip_a"] - p @ a), "from_center_a_mm": 1000 * float(p @ a - f["center_a"]), "across_w_mm": 1000 * float(p @ w - f["center_w"]),
                               "depth_mm": 1000 * float(p @ pf["c"] - f["face_c"]), "normal_N": float(f6[0]), "beaker_geom": model.geom(g1 if g1 in bg else g2).name})
    return res


def summarize_contacts(lst):
    if not lst:
        return None
    F = np.array([x["normal_N"] for x in lst])
    arr = lambda k: np.array([x[k] for x in lst])
    wc = lambda k: float((arr(k) * F).sum() / max(F.sum(), 1e-12))
    return {"n_points": len(lst), "total_N": float(F.sum()), "from_tip_mm_weighted": wc("from_tip_mm"), "from_center_a_mm_weighted": wc("from_center_a_mm"), "across_w_mm_weighted": wc("across_w_mm"),
            "from_tip_mm_range": [float(arr("from_tip_mm").min()), float(arr("from_tip_mm").max())], "across_w_mm_range": [float(arr("across_w_mm").min()), float(arr("across_w_mm").max())],
            "depth_mm_range": [float(arr("depth_mm").min()), float(arr("depth_mm").max())], "beaker_geoms": sorted({x["beaker_geom"] for x in lst})}


def make_sampler(model, data):
    bb = model.body("task_beaker").id
    beaker = descendants(model, "task_beaker")
    bg = {g for g in range(model.ngeom) if int(model.geom_bodyid[g]) in beaker}
    fgs = {}
    for k in ("left_finger", "right_finger"):
        b = model.body(f"openarm_{SIDE}_{k}").id
        fgs[k] = {g for g in range(model.ngeom) if int(model.geom_bodyid[g]) == b and (model.geom_contype[g] or model.geom_conaffinity[g])}
    R = {"moments": {}, "snap": None, "extent": {k: {"from_tip": [1e9, -1e9], "across_w": [1e9, -1e9], "n_ticks": 0} for k in fgs}, "prev_label": None, "last_by_label": {}}

    def report(tag):
        pf = pad_frames(model, data)
        cs = contacts_on_pads(model, data, bg, fgs, pf)
        p_pad, Rm = H["arm"].pad_pose(data)
        bpos = data.xpos[bb].copy()
        Rb = data.xmat[bb].reshape(3, 3)
        axis = Rb[:, 2].copy()
        v = pf["pad_center_world"] - bpos
        perp = v - (v @ axis) * axis
        com = data.xipos[bb]
        tips = {k: pf["fingers"][k]["tip_a"] for k in pf["fingers"]}
        axis_a = float(bpos @ pf["a"])                               # the beaker axis position along the approach axis
        R["moments"][tag] = {"t": float(data.time), "tilt_deg": float(np.degrees(np.arccos(np.clip(axis[2], -1, 1)))),
                             "pad_frame": {k: {kk: vv for kk, vv in f.items() if kk != "geoms"} for k, f in pf["fingers"].items()},
                             "contacts": {k: summarize_contacts(v_) for k, v_ in cs.items()},
                             "axis_to_pad_center": {"perpendicular_mm": 1000 * float(np.linalg.norm(perp)), "along_approach_mm": 1000 * float(perp @ pf["a"]), "along_closing_mm": 1000 * float(perp @ pf["c"]),
                                                    "along_across_mm": 1000 * float(perp @ pf["w"]), "vertical_pad_above_bottom_mm": 1000 * float(v @ axis)},
                             "tips_past_axis_mm": {k: 1000 * (t - axis_a) for k, t in tips.items()},
                             "pad_center_from_tip_mm": {k: 1000 * (pf["fingers"][k]["tip_a"] - pf["pad_center_world"] @ pf["a"]) for k in pf["fingers"]},
                             "com_above_bottom_mm": 1000 * float((com - bpos) @ axis), "pad_center_above_bottom_mm": 1000 * float((pf["pad_center_world"] - bpos) @ axis), "com_rel_pad_center_mm": [1000 * float(x) for x in (com - pf["pad_center_world"])]}
        return cs, pf

    def step(obs):
        arm, S = H["arm"], H["S"]
        if arm is None:
            return None
        steps = S.get("steps") or []
        cur = steps[S["i"]] if S.get("i") is not None and S["i"] < len(steps) else None
        prim = S["ctx"].get("primitive")
        label = f"{prim}:{cur['name']}" if cur is not None else f"{prim}:-"
        # the end of the closing: the first tick of the lift
        if label == "pick:UP" and R["prev_label"] == "pick:CLOSE":
            report("end_of_closing")
            R["snap"] = mujoco.MjData(model)
            mujoco.mj_copyData(R["snap"], model, data)
        if label == "pick:CHECK":
            R["last_by_label"]["handoff"] = True
        if label == "place:OVER" and R["prev_label"] == "pick:CHECK":
            pass
        # the extents over the whole hold: from the lift to the end of the place's DOWN
        if label in ("pick:UP", "pick:CHECK", "place:OVER", "place:DOWN"):
            pf = pad_frames(model, data) if (len(R.setdefault("ticks", [])) % 5 == 0) else R.get("pf")
            R["pf"] = pf
            R["ticks"].append(1)
            cs = contacts_on_pads(model, data, bg, fgs, pf)
            for k, lst in cs.items():
                if lst:
                    e = R["extent"][k]
                    e["n_ticks"] += 1
                    for x in lst:
                        e["from_tip"] = [min(e["from_tip"][0], x["from_tip_mm"]), max(e["from_tip"][1], x["from_tip_mm"])]
                        e["across_w"] = [min(e["across_w"][0], x["across_w_mm"]), max(e["across_w"][1], x["across_w_mm"])]
        if label == "place:DOWN":
            R["last_down_tick"] = float(data.time)
            R["down_state"] = mujoco.MjData(model)
            mujoco.mj_copyData(R["down_state"], model, data)
        if label not in ("pick:CHECK",) and R["prev_label"] == "pick:CHECK" and "end_of_lift" not in R["moments"]:
            report("end_of_lift")
        R["prev_label"] = label
        return None
    return {"name": "pad_sampler", "step": step, "state": R, "bg": bg}


def clearance_scan(model, snap, pf, bg_ids, shifts_mm):
    """On the copy of the state at the end of the closing: the beaker moved toward the palm (against the approach axis) by each shift; the smallest distance of the beaker's geoms to the palm / hand body,
    to the fingers, and to the other arm parts (link7 and below)."""
    d = mujoco.MjData(model)
    mujoco.mj_copyData(d, model, snap)
    j = model.joint("task_beaker_free")
    qa = int(j.qposadr[0])
    base = d.qpos[qa:qa + 3].copy()
    hand = model.body(f"openarm_{SIDE}_hand").id
    fingers = {model.body(f"openarm_{SIDE}_left_finger").id, model.body(f"openarm_{SIDE}_right_finger").id}
    arm_bodies = {b for b in range(model.nbody) if model.body(b).name.startswith(f"openarm_{SIDE}_") and b not in fingers and b != hand}
    geoms_of = lambda bodies: [g for g in range(model.ngeom) if int(model.geom_bodyid[g]) in bodies and (model.geom_contype[g] or model.geom_conaffinity[g])]
    gh, gf, ga = geoms_of({hand}), geoms_of(fingers), geoms_of(arm_bodies)
    out = []
    ft = np.zeros(6)
    for s in shifts_mm:
        d.qpos[qa:qa + 3] = base - pf["a"] * (s / 1000.0)
        mujoco.mj_kinematics(model, d)
        mujoco.mj_comPos(model, d)

        def dmin(gs):
            best = 1e9
            for gb in bg_ids:
                for g in gs:
                    if not (model.geom_contype[gb] or model.geom_conaffinity[gb]):
                        continue
                    best = min(best, mujoco.mj_geomDistance(model, d, gb, g, 0.2, ft))
            return 1000 * float(best)
        out.append({"shift_mm": s, "to_palm_mm": dmin(gh), "to_fingers_mm": dmin(gf), "to_other_arm_parts_mm": dmin(ga)})
    return out


def model_facts(model):
    facts = {"finger_geoms": [], "pairs": []}
    for k in ("left_finger", "right_finger"):
        b = model.body(f"openarm_{SIDE}_{k}").id
        for g in range(model.ngeom):
            if int(model.geom_bodyid[g]) == b and (model.geom_contype[g] or model.geom_conaffinity[g]):
                mid = int(model.geom_dataid[g])
                facts["finger_geoms"].append({"name": model.geom(g).name, "type": mujoco.mjtGeom(model.geom_type[g]).name, "mesh": model.mesh(mid).name if mid >= 0 else None, "friction": [float(x) for x in model.geom_friction[g]],
                                              "condim": int(model.geom_condim[g]), "solref": [float(x) for x in model.geom_solref[g]], "solimp": [float(x) for x in model.geom_solimp[g]]})
    for i in range(model.npair):
        g1, g2 = int(model.pair_geom1[i]), int(model.pair_geom2[i])
        n1, n2 = model.body(int(model.geom_bodyid[g1])).name, model.body(int(model.geom_bodyid[g2])).name
        if SIDE in n1 + n2 and ("finger" in n1 + n2 or "hand" in n1 + n2):
            facts["pairs"].append({"bodies": [n1, n2], "condim": int(model.pair_dim[i]), "friction": [float(x) for x in model.pair_friction[i]], "solref": [float(x) for x in model.pair_solref[i]]})
            if len(facts["pairs"]) >= 4:
                break
    facts["cone"] = int(model.opt.cone)
    facts["impratio"] = float(model.opt.impratio)
    facts["noslip_iterations"] = int(model.opt.noslip_iterations)
    return facts


def main(args):
    cfg = {**BEAKER_CFG, "liquid_mass": 0.10}
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    task = make_pipeline_task(PLAN4, module_hook=make_hook())
    gc.collect()
    sim = load_task(TASK_CFG, cameras=True, beaker_cfg=cfg)
    holder = {}

    def extra(m, d):
        holder["s"] = make_sampler(m, d)
        return {"pad_sampler": holder["s"]}
    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", extra_sources=extra, stop_after_handoff_s=None)
    st = holder["s"]["state"]
    model = sim.model
    res = {"outcome": s["outcome"], "true_total_kg": float(model.body_mass[model.body("task_beaker").id]), "moments": st["moments"], "extent_over_lift_and_carry": st["extent"], "facts": model_facts(model),
           "grasp_height_frac": PICK_PLACE_CFG["grasp_height_frac"], "beaker_height_m": BEAKER_CFG["height"], "tol_m": PICK_PLACE_CFG["tol_m"]}
    if st["snap"] is not None:
        pf = pad_frames(model, st["snap"])
        res["clearance_scan"] = clearance_scan(model, st["snap"], pf, sorted(holder["s"]["bg"]), [0, 5, 10, 15, 20, 25, 30])
        res["pad_size_at_closing"] = {k: {kk: vv for kk, vv in f.items() if kk in ("length_mm", "width_mm", "n_vertices", "geoms")} for k, f in pf["fingers"].items()}
    tmp = out / "result.json.tmp"
    tmp.write_text(json.dumps(res, indent=1, default=str))
    tmp.replace(out / "result.json")
    print("outcome", s["outcome"], "moments", list(st["moments"]), flush=True)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", required=True)
    main(ap.parse_args())
